<?php $pageTitle='Dashboard';require '../includes/admin-header.php';$pdo=db();$metrics=['Total Users'=>"SELECT COUNT(*) FROM users",'Active Users'=>"SELECT COUNT(*) FROM users WHERE status='active'",'Blocked Users'=>"SELECT COUNT(*) FROM users WHERE status='blocked'",'Total Products'=>"SELECT COUNT(*) FROM products",'Total Categories'=>"SELECT COUNT(*) FROM categories",'Total Orders'=>"SELECT COUNT(*) FROM orders",'Pending Orders'=>"SELECT COUNT(*) FROM orders WHERE order_status='pending'",'Completed Orders'=>"SELECT COUNT(*) FROM orders WHERE order_status='delivered'",'Total Sales'=>"SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE payment_status='paid'",'Low Stock Products'=>"SELECT COUNT(*) FROM products WHERE stock_quantity BETWEEN 1 AND 8"];$values=[];foreach($metrics as $key=>$sql)$values[$key]=$pdo->query($sql)->fetchColumn();$recent=$pdo->query('SELECT o.*,u.full_name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 5')->fetchAll();$low=$pdo->query('SELECT * FROM products WHERE stock_quantity BETWEEN 1 AND 8 ORDER BY stock_quantity')->fetchAll(); ?>
<div class="row g-3 mb-4"><?php foreach($values as $label=>$value): ?><div class="col-6 col-lg"><div class="card card-body h-100"><small><?=e($label)?></small><strong class="fs-4"><?=str_contains($label,'Sales')?money($value):$value?></strong></div></div><?php endforeach ?></div><div class="row g-4"><div class="col-lg-7"><div class="card card-body"><h5>Recent orders</h5><table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $o): ?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['full_name'])?></td><td><?=money($o['total_amount'])?></td><td><?=e($o['order_status'])?></td></tr><?php endforeach ?></tbody></table></div></div><div class="col-lg-5"><div class="card card-body"><h5>Low-stock T-shirts</h5><?php foreach($low as $p): ?><p class="border-bottom pb-2 mb-2"><?=e($p['name'])?> <b class="float-end"><?=$p['stock_quantity']?> left</b></p><?php endforeach ?></div></div></div><?php require '../includes/admin-footer.php'; ?>
